package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class SlaAlertsAcceptance {
    static final long START=PlatformFoundationTest.at("2026-11-17T09:00:00Z");
    static final String NOTICES="/api/openservice/me/notifications";
    static String context(String id){return "/api/openservice/notifications/"+id+"/context";}
    static List<Map<String,Object>> notices(WorkflowSupport h,String user)throws Exception{var response=h.get(NOTICES,auth(user));assertEquals(200,response.statusCode());return objects(parsed(response).get("result"));}
    static String start(WorkflowSupport h,String record)throws Exception{String calendar="Alerts"+id();PlatformOperationsAcceptance.post(h,"calendars",map("name",calendar,"calendar",PlatformFoundationTest.calendar()));String clock=PlatformOperationsAcceptance.post(h,"clocks",map("table","incident","record_id",record,"calendar",calendar,"minutes",1)).get("sla_id").toString();try(var db=h.store.open()){db.update("UPDATE os_sla SET last_tick=? WHERE sla_id=?",START,clock);db.connection.commit();}return clock;}
    static void tick(Store store,long time)throws Exception{try(var db=store.open()){String actor=PlatformFoundationTest.bind(db);ServiceClocks.tick(db,time);assertEquals(actor,db.viewerId);assertEquals("admin",db.viewerRole);db.connection.commit();}}
    static void assign(WorkflowSupport h,String record,String username,String group)throws Exception{assertEquals(200,h.json("PATCH","/api/now/table/incident/"+record,map("assigned_to",username,"assignment_group",group),auth("admin")).statusCode());}
    static void run(WorkflowSupport h)throws Exception{
        h.account("BreachAssignee","agent");h.account("BreachManager","agent");h.account("FormerAssignee","agent");String record=h.add("incident").get("sys_id").toString(),group;try(var db=h.store.open()){PlatformFoundationTest.bind(db);group=Service.create(db,"sys_user_group",map("short_description","Alert group","manager","BreachManager"),"admin").get("sys_id").toString();db.connection.commit();}assign(h,record,"FormerAssignee",group);String clock=start(h,record);assign(h,record,"BreachAssignee",group);tick(h.store,START+59999);assertTrue(notices(h,"BreachAssignee").isEmpty());tick(h.store,START+60000);assertEquals(1,notices(h,"BreachAssignee").size());assertEquals(1,notices(h,"BreachManager").size());assertTrue(notices(h,"FormerAssignee").isEmpty());assertEquals(clock,notices(h,"admin").getFirst().get("notice_id"));String notice=notices(h,"BreachAssignee").getFirst().get("notice_id").toString();assertEquals(1L,((Number)notices(h,"BreachAssignee").getFirst().get("has_target")).longValue());assertFalse(notices(h,"BreachAssignee").getFirst().get("message").toString().contains(record));
        String target="/record/incident/"+record+"/clocks";assertEquals(target,TransferAcceptance.result(h.get(context(notice),auth("BreachAssignee")),200).get("url"));assertEquals(200,h.get(target,auth("BreachAssignee")).statusCode());assertEquals(302,h.get("/account/notifications/"+notice+"/context",auth("BreachAssignee")).statusCode());assertEquals(404,h.get(context(notice),auth("BreachManager")).statusCode());assertEquals(401,h.get(context(notice),null).statusCode());assertEquals(404,h.get(context(id()),auth("BreachAssignee")).statusCode());assertEquals(400,h.get(context(notice)+"?bad=x",auth("BreachAssignee")).statusCode());assertEquals(405,h.json("POST",context(notice),map(),auth("BreachAssignee")).statusCode());assertEquals(200,h.json("POST",NOTICES,map("acknowledge",notice),auth("BreachAssignee")).statusCode());new Store(h.environment);tick(h.store,START+120000);assertEquals(1,notices(h,"BreachAssignee").size());assertEquals(1,notices(h,"BreachAssignee").getFirst().get("acknowledged"));
        try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"incident",record),actor,map("visibility","private","owner_id",actor));db.connection.commit();}assertEquals(404,h.get(context(notice),auth("BreachAssignee")).statusCode());
        Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("admin")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(denied));db.connection.commit();}try{assertEquals(403,h.get(context(notice),auth("BreachAssignee")).statusCode());}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}}
        try(var db=h.store.open()){db.update("UPDATE os_notice_target SET kind='unknown' WHERE notice_id=?",notice);db.connection.commit();}assertEquals(404,h.get(context(notice),auth("BreachAssignee")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_notice_target SET kind='clock' WHERE notice_id=?",notice);db.update("DELETE FROM os_sla WHERE sla_id=?",clock);db.connection.commit();}assertEquals(404,h.get(context(notice),auth("BreachAssignee")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_notice WHERE notice_id=?",notice);db.connection.commit();}var env=new org.springframework.mock.env.MockEnvironment();env.merge((org.springframework.core.env.ConfigurableEnvironment)h.environment);env.setProperty("WORK_ENABLED","true");new WorkWorker(new Store(env)).tick();try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_notice_target WHERE notice_id=?",notice));}
    }
    static void boundaries(WorkflowSupport h)throws Exception{
        h.account("AlertStaff","agent");String record=h.add("incident").get("sys_id").toString();assign(h,record,"AlertStaff","");Map<String,Object> schema;String staff;try(var db=h.store.open()){schema=Service.schema(db,"incident");staff=db.one("SELECT user_id FROM os_user WHERE name='AlertStaff'").get("user_id").toString();}
        try{
            for(String setting:List.of("notifications=0","active=0","role='reader'","password_reset_required=1")){
                try(var db=h.store.open()){db.update("UPDATE os_user SET notifications=1,active=1,role='agent',password_reset_required=0 WHERE user_id=?",staff);db.update("UPDATE os_user SET "+setting+" WHERE user_id=?",staff);db.connection.commit();}String clock=start(h,record);tick(h.store,START+60000);try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_notice WHERE user_id=?",staff));assertEquals("breached",db.one("SELECT state FROM os_sla WHERE sla_id=?",clock).get("state"));}
            }
            try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);db.update("UPDATE os_user SET notifications=1,active=1,role='agent',password_reset_required=0 WHERE user_id=?",staff);RecordAccess.change(db,Service.record(db,"incident",record),actor,map("visibility","private","owner_id",actor));db.connection.commit();}start(h,record);tick(h.store,START+60000);assertTrue(notices(h,"AlertStaff").isEmpty());
            try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"incident",record),actor,map("visibility","workspace","owner_id",""));var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("reader")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(denied));db.connection.commit();}
            // An already running clock can outlive a table-policy change; neither admin owner nor staff receive it.
            try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}String deniedClock=start(h,record);long before;try(var db=h.store.open()){before=db.count("SELECT COUNT(*) FROM os_notice");var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("reader")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(denied));db.connection.commit();}tick(h.store,START+60000);try(var db=h.store.open()){assertEquals(before,db.count("SELECT COUNT(*) FROM os_notice"));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}
            assign(h,record,"admin","");String same=start(h,record);tick(h.store,START+60000);try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_notice_target WHERE target_id=?",same));}
            assign(h,record,"No-longer-existing-account","");String unknown=start(h,record);tick(h.store,START+60000);try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_notice_target WHERE target_id=?",unknown));}
            assign(h,record,"AlertStaff","");String groupClock=start(h,record);try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db),group=Service.create(db,"sys_user_group",map("short_description","Withdrawn team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,staff);RecordAccess.change(db,Service.record(db,"incident",record),actor,map("visibility","group","group_id",group));db.update("DELETE FROM os_group_member WHERE group_id=? AND user_id=?",group,staff);db.connection.commit();}tick(h.store,START+60000);assertTrue(notices(h,"AlertStaff").isEmpty());
            String deleted=start(h,record);try(var db=h.store.open()){db.update("DELETE FROM os_record WHERE sys_id=?",record);db.connection.commit();}tick(h.store,START+60000);try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_notice WHERE notice_id=?",deleted));assertEquals("breached",db.one("SELECT state FROM os_sla WHERE sla_id=?",deleted).get("state"));}
        }finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}}
    }
}
